import{_ as a,o as t,c as s,a2 as o}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"Lesson 7: Your First Conversation — Completing a Task End to End","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/module-2/lesson-7.md","filePath":"en/modules/module-2/lesson-7.md"}'),i={name:"en/modules/module-2/lesson-7.md"};function n(l,e,r,d,p,c){return t(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="lesson-7-your-first-conversation-—-completing-a-task-end-to-end" tabindex="-1">Lesson 7: Your First Conversation — Completing a Task End to End <a class="header-anchor" href="#lesson-7-your-first-conversation-—-completing-a-task-end-to-end" aria-label="Permalink to &quot;Lesson 7: Your First Conversation — Completing a Task End to End&quot;">​</a></h1><blockquote><p>📌 <strong>Learning Objectives</strong>: Complete Codex&#39;s first real conversation and experience the full process from inputting a command to getting results ⏱️ <strong>Estimated Time</strong>: 20 minutes 🎯 <strong>Teaching Rhythm</strong>: Hands-on practice</p></blockquote><hr><h2 id="i-the-simplest-start-ask-a-question" tabindex="-1">I. The Simplest Start: Ask a Question <a class="header-anchor" href="#i-the-simplest-start-ask-a-question" aria-label="Permalink to &quot;I. The Simplest Start: Ask a Question&quot;">​</a></h2><p>Open Codex and type this into the chat box:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>What are the latest AI news today?</span></span></code></pre></div><p>Press Enter (or click Send).</p><p>Codex will search the web for the latest AI-related news and give you a summary. You might see a response like this:</p><blockquote><p>Here are some important AI news items from today:</p><ol><li>OpenAI released the latest progress on GPT-5...</li><li>Google DeepMind published a new paper in Nature...</li><li>...</li></ol></blockquote><p>This is Codex&#39;s most basic capability: <strong>Web Search + Information Organization</strong>.</p><hr><h2 id="ii-let-it-do-something-practical" tabindex="-1">II. Let It Do Something Practical <a class="header-anchor" href="#ii-let-it-do-something-practical" aria-label="Permalink to &quot;II. Let It Do Something Practical&quot;">​</a></h2><p>Now let&#39;s do a more useful task.</p><h3 id="task-analyze-a-folder-on-your-computer" tabindex="-1">Task: Analyze a Folder on Your Computer <a class="header-anchor" href="#task-analyze-a-folder-on-your-computer" aria-label="Permalink to &quot;Task: Analyze a Folder on Your Computer&quot;">​</a></h3><ol><li>Open a folder as the workspace in Codex (e.g., your &quot;Downloads&quot; folder, or a test folder you created specifically for this).</li><li>Type this into the chat box:<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Help me analyze this folder. Count how many files there are and show me the breakdown by file type.</span></span></code></pre></div></li><li>Watch Codex&#39;s execution process: <ul><li>It lists the files in the folder</li><li>Counts the quantity of each type</li><li>Generates a summary report</li></ul></li></ol><h3 id="what-you-might-see" tabindex="-1">What You Might See: <a class="header-anchor" href="#what-you-might-see" aria-label="Permalink to &quot;What You Might See:&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Folder Analysis Report:</span></span>
<span class="line"><span>- Total files: 47</span></span>
<span class="line"><span>- By type:</span></span>
<span class="line"><span>  - PDF documents: 12</span></span>
<span class="line"><span>  - JPEG images: 8</span></span>
<span class="line"><span>  - MP4 videos: 5</span></span>
<span class="line"><span>  - ZIP archives: 3</span></span>
<span class="line"><span>  - Others: 19</span></span></code></pre></div><hr><h2 id="iii-advanced-task-organize-a-folder" tabindex="-1">III. Advanced Task: Organize a Folder <a class="header-anchor" href="#iii-advanced-task-organize-a-folder" aria-label="Permalink to &quot;III. Advanced Task: Organize a Folder&quot;">​</a></h2><p>If just &quot;looking&quot; isn&#39;t exciting enough, let Codex help you &quot;do&quot; it:</p><h3 id="task-organize-a-messy-folder" tabindex="-1">Task: Organize a Messy Folder <a class="header-anchor" href="#task-organize-a-messy-folder" aria-label="Permalink to &quot;Task: Organize a Messy Folder&quot;">​</a></h3><ol><li>Prepare a folder containing various files (if you don&#39;t have one, just create a few different types of files randomly).</li><li>Type this into the chat box:<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Help me organize this folder. Put similar files into the same subfolder.</span></span></code></pre></div></li><li>Codex will: <ul><li>Scan all files</li><li>Create subfolders based on file extensions (e.g., <code>images/</code>, <code>documents/</code>, <code>videos/</code>)</li><li>Move files into the corresponding subfolders.</li></ul></li></ol><blockquote><p>⚠️ <strong>Note</strong>: Before executing file move operations, Codex will usually ask for your confirmation. This is a built-in safety mechanism of the default permission mode.</p></blockquote><hr><h2 id="iv-observe-how-codex-executes-tasks-step-by-step" tabindex="-1">IV. Observe How Codex Executes Tasks Step by Step <a class="header-anchor" href="#iv-observe-how-codex-executes-tasks-step-by-step" aria-label="Permalink to &quot;IV. Observe How Codex Executes Tasks Step by Step&quot;">​</a></h2><p>When you input a command, Codex&#39;s workflow is:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>You input command → Codex understands intent → Codex reads relevant files → Codex makes a plan → Codex executes → You review the result</span></span></code></pre></div><p>Every step is traceable. You can see its thinking process and operation steps in Codex&#39;s execution log.</p><hr><h2 id="v-in-lesson-practice-checklist" tabindex="-1">V. In-Lesson Practice Checklist <a class="header-anchor" href="#v-in-lesson-practice-checklist" aria-label="Permalink to &quot;V. In-Lesson Practice Checklist&quot;">​</a></h2><p>Complete the following tasks in order:</p><ul><li>[ ] Ask Codex a simple question (e.g., &quot;What&#39;s the weather today?&quot;)</li><li>[ ] Set a folder as the workspace</li><li>[ ] Have Codex analyze the folder&#39;s contents</li><li>[ ] Have Codex organize the folder&#39;s files</li><li>[ ] Observe Codex&#39;s execution log</li></ul><hr><h2 id="vi-summary" tabindex="-1">VI. Summary <a class="header-anchor" href="#vi-summary" aria-label="Permalink to &quot;VI. Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Knowledge Point</th><th>Core Content</th></tr></thead><tbody><tr><td>First conversation</td><td>Start with a simple question to build confidence</td></tr><tr><td>Folder analysis</td><td>Have Codex count and categorize files</td></tr><tr><td>Folder organization</td><td>Have Codex automatically sort files</td></tr><tr><td>Execution flow</td><td>Understand → Plan → Execute → Review</td></tr></tbody></table><hr><h2 id="vii-next-step" tabindex="-1">VII. Next Step <a class="header-anchor" href="#vii-next-step" aria-label="Permalink to &quot;VII. Next Step&quot;">​</a></h2><p><a href="./../module-3/lesson-8.html">→ Enter Module 3: Core Features</a></p>`,38)])])}const m=a(i,[["render",n]]);export{u as __pageData,m as default};
